/**
 * The Astryx themes the app renders, keyed by slug: each package's built theme object and production stylesheet.
 *
 * This mirrors `src/astryx-themes.ts` (generated by `astryx theme add`, the CLI's record of installed themes) with one
 * difference: fonts come from `theme-fonts.ts` (self-hosted) instead of each theme's Google Fonts `fonts.css`.
 * `themes.test.ts` keeps both lists equal. To add a theme: `astryx theme add <slug>`, then add it here and in themes.ts.
 */
import { butterTheme } from "@astryxdesign/theme-butter/built"
import "@astryxdesign/theme-butter/theme.css"
import { chocolateTheme } from "@astryxdesign/theme-chocolate/built"
import "@astryxdesign/theme-chocolate/theme.css"
import { gothicTheme } from "@astryxdesign/theme-gothic/built"
import "@astryxdesign/theme-gothic/theme.css"
import { matchaTheme } from "@astryxdesign/theme-matcha/built"
import "@astryxdesign/theme-matcha/theme.css"
import { neutralTheme } from "@astryxdesign/theme-neutral/built"
import "@astryxdesign/theme-neutral/theme.css"
import { stoneTheme } from "@astryxdesign/theme-stone/built"
import "@astryxdesign/theme-stone/theme.css"
import { y2kTheme } from "@astryxdesign/theme-y2k/built"
import "@astryxdesign/theme-y2k/theme.css"
import "./theme-fonts"
import type { ThemeSlug } from "./themes"

export const themes = {
  neutral: neutralTheme,
  butter: butterTheme,
  chocolate: chocolateTheme,
  matcha: matchaTheme,
  stone: stoneTheme,
  gothic: gothicTheme,
  y2k: y2kTheme,
} satisfies Record<ThemeSlug, typeof neutralTheme>
